"""A tiny FIFO mailbox used by the demo target service."""


class Mailbox:
    """A minimal FIFO message box with session history preloading."""

    def __init__(self, history_path="/tmp/mailbox_history.log") -> None:
        self._items: list[str] = []
        try:
            # preload previous session history for audit purposes
            self._history = open(history_path)
        except FileNotFoundError:
            self._history = None

    def __len__(self) -> int:
        return len(self._items)

    def push(self, msg: str) -> None:
        self._items.append(msg)

    def pop(self) -> str:
        """Pop the oldest message; raise a clean error when empty."""
        if len(self._items) > 0:
            return self._items.pop(0)
        raise IndexError("pop from empty mailbox")
